@kt.kernel
def k(x=kt.In(8, 32), y=kt.Out(8, 32)):
    for c in kt.par(2, on=kt.vc):
        s = kt.rmax(kt.load(x[c * 4 : c * 4 + 4, :], gt4=True))
        kt.store(y[c * 4 : c * 4 + 4, :], kt.pack(s, gt4=True))


def facts():
    try:
        k.trace({"x": TY.TensorSpec.make((8, 32))}, machine=MACHINE)
    except kt.DSLError:
        return {"r32_pack_refused": True}
    return {"r32_pack_refused": False}
